export const GLOSSARY_SHARD = Object.freeze({"bitcoin":{"slug":"bitcoin","cat":"basics","en":"Bitcoin (BTC)","contentLocale":"tr","term":"Bitcoin (BTC)","aka":["BTC","bitcoin"],"short":"Bitcoin (BTC), 2009'da Satoshi Nakamoto takma adıyla başlatılan, iş ispatı ile çalışan ve toplam arzı 21 milyon BTC ile sınırlı olan ilk ve piyasa değeri en büyük kripto paradır.","body":["Bitcoin, hiçbir şirketin veya devletin yönetmediği açık bir ağdır. İşlemleri madenciler bloklara ekler ve bunun karşılığında yeni basılan BTC ile işlem ücretlerini kazanır. Ortalama her 10 dakikada bir yeni blok üretilir.","Arzın 21 milyonla sınırlı olması ve yaklaşık dört yılda bir yaşanan halving ile yeni arzın yarıya inmesi, Bitcoin'in sık sık dijital altına benzetilmesinin nedenidir. Nisan 2024 halving'inden sonra blok ödülü 3,125 BTC oldu.",["Bitcoin bölünebilir: en küçük birimi ",["satoshi","satoshi"],"'dir ve 1 BTC 100.000.000 satoshi eder. Yani tam bir Bitcoin almak zorunda değilsiniz. ABD'de ",["spot Bitcoin ETF","spot-bitcoin-etf"],"'leri Ocak 2024'te işlem görmeye başladı; bu da kurumsal yatırımcılara yeni bir erişim yolu açtı."]],"example":["BTC'nin 64.000 ",["USDT","usdt"]," olduğu bir anda 320 USDT'lik alım yaptığınızı varsayalım. 320 / 64.000 = 0,005 BTC alırsınız; bu da 500.000 satoshi demektir. Fiyat 72.000 USDT'ye çıkarsa pozisyonunuz 0,005 x 72.000 = 360 USDT olur, yani 40 USDT kâr. Fiyat 56.000 USDT'ye düşerse değeri 280 USDT'ye iner. Hesaba alım ve satım işlem ücretlerini, borsadan cüzdana çekiyorsanız çekim ücretini de eklemeniz gerekir."],"mistakes":["Bir Bitcoin'in tamamını almak gerektiğini düşünüp küçük miktarlarla başlamamak.","BTC'yi Bitcoin ağını desteklemeyen bir adrese veya yanlış bir ağ üzerinden göndermek.","Sınırlı arzın fiyatın her zaman yükseleceği anlamına geldiğini varsaymak; fiyat talebe de bağlıdır."],"faq":[{"q":"Bitcoin'i kim çıkardı?","a":"Bitcoin, 2008'de Satoshi Nakamoto takma adıyla yayımlanan bir makaleyle tanıtıldı ve ağ Ocak 2009'da başladı. Satoshi Nakamoto'nun gerçek kimliği bilinmiyor."},{"q":"Toplam kaç Bitcoin var?","a":"Maksimum arz 21 milyon BTC'dir. Bunun büyük kısmı zaten üretilmiştir; kalan miktar halving'ler nedeniyle giderek yavaşlayan bir hızla madenciler aracılığıyla piyasaya girer."},{"q":"Bitcoin'in yarısını veya küçük bir kısmını alabilir miyim?","a":"Evet. Bitcoin sekiz ondalık basamağa kadar bölünebilir, bu yüzden borsanın izin verdiği en düşük tutardan başlayarak istediğiniz kadar alabilirsiniz."}],"title":"Bitcoin (BTC) nedir? Nasıl çalışır?","description":"Bitcoin'in nasıl çalıştığını, 21 milyon arz sınırını, halving'i ve küçük miktarlarda nasıl alınabildiğini öğrenin.","related":[["satoshi","Satoshi (sats)","Satoshi (sats), Bitcoin'in en küçük birimidir; 1 BTC 100.000.000 satoshi'ye eşittir ve adını Bitcoin'in takma adlı yaratıcısı Satoshi Nakamoto'dan alır."],["bitcoin-halving","Bitcoin halving (yarılanma)","Bitcoin halving (yarılanma), yaklaşık her dört yılda bir, yani her 210.000 blokta bir, madencilere verilen blok ödülünün kod gereği yarıya indirildiği olaydır."],["proof-of-work","İş ispatı (Proof of Work, PoW)","İş ispatı (Proof of Work, PoW), madencilerin zor bir matematik bulmacasını çözmek için bilgi işlem gücü harcadığı ve bulmacayı ilk çözenin yeni bloğu ekleyip ödül kazandığı bir blockchain uzlaşma mekanizmasıdır."],["mining","Kripto madenciliği (mining)","Kripto madenciliği, iş ispatı kullanan blockchain'lerde özel donanımlarla hesaplama yapılarak işlemlerin bloklara eklenmesi ve karşılığında yeni basılan coin ile işlem ücretlerinin kazanılması sürecidir."],["spot-bitcoin-etf","Spot Bitcoin ETF","Spot Bitcoin ETF, gerçek bitcoin satın alıp saklayan ve borsada hisse senedi gibi işlem gören, fiyatı bitcoin'in piyasa fiyatını takip eden bir borsa yatırım fonudur."]],"lesson":{"id":"E01","slug":"can-i-buy-part-of-a-bitcoin","ep":1,"title":"Bir bitcoin o kadar pahalıyken yine de biraz alabilir miyim?"},"coin":{"slug":"bitcoin","name":"Bitcoin","symbol":"BTC"},"tool":null,"cta":true},"proof-of-work":{"slug":"proof-of-work","cat":"basics","en":"Proof of work (PoW)","contentLocale":"tr","term":"İş ispatı (Proof of Work, PoW)","aka":["PoW","proof of work","iş kanıtı"],"short":"İş ispatı (Proof of Work, PoW), madencilerin zor bir matematik bulmacasını çözmek için bilgi işlem gücü harcadığı ve bulmacayı ilk çözenin yeni bloğu ekleyip ödül kazandığı bir blockchain uzlaşma mekanizmasıdır.","body":["Madenciler, blok verisine rastgele sayılar ekleyerek belirli bir hedefin altında kalan bir hash bulmaya çalışır. Bunun kısayolu yoktur; tek yol milyarlarca deneme yapmaktır. Bulunan sonucu doğrulamak ise herkes için çok kolaydır.","Bu harcanan enerji ve donanım, ağın güvenliğini sağlar. Geçmişi değiştirmek isteyen birinin ağın toplam hash gücünün çoğunluğunu kontrol etmesi gerekir; buna yüzde 51 saldırısı denir ve büyük ağlarda son derece maliyetlidir.",[["Bitcoin","bitcoin"],", Litecoin ve Dogecoin iş ispatı kullanır. ",["Ethereum","ethereum"]," ise Eylül 2022'deki Merge ile hisse ispatına geçti. PoW'un en çok eleştirilen yanı yüksek enerji tüketimidir; savunucuları ise bu maliyetin ağı fiziksel olarak korunur hale getirdiğini söyler."]],"example":"Bitcoin ağı, blokların ortalama 10 dakikada bir bulunmasını hedefler. Her 2.016 blokta, yani yaklaşık iki haftada bir, zorluk ayarlanır. Son 2.016 blok 10 dakika yerine ortalama 8 dakikada bulunduysa ağ zorluğu yaklaşık 10 / 8 = 1,25 kat artırır. Bloklar ortalama 12 dakikada bulunduysa zorluk yaklaşık 10 / 12 = 0,83 katına iner. Böylece madenci sayısı değişse de blok süresi hedefe yakın kalır.","mistakes":["Madencilerin işlemleri onaylamak dışında anlamsız işler yaptığını düşünmek; harcanan iş ağın güvenliğini sağlar.","Her kripto paranın madencilikle üretildiğini varsaymak; birçok ağ hisse ispatı kullanır.","Ev bilgisayarıyla Bitcoin madenciliğinin kârlı olacağını sanmak; ağ özel ASIC cihazlarıyla rekabet eder."],"faq":[{"q":"Proof of Work ile Proof of Stake arasındaki fark nedir?","a":"PoW'da blok üretme hakkı harcanan bilgi işlem gücüyle, PoS'ta ise kilitlenen (stake edilen) coin miktarıyla kazanılır. PoS çok daha az enerji tüketir, PoW ise fiziksel maliyete dayalı güvenlik sağlar."},{"q":"Hangi kripto paralar PoW kullanıyor?","a":"En bilinenleri Bitcoin, Litecoin, Dogecoin ve Bitcoin Cash'tir. Ethereum 2022'ye kadar PoW kullanıyordu."}],"title":"Proof of Work (PoW) nedir? İş ispatı nasıl çalışır?","description":"İş ispatının (PoW) nasıl çalıştığını, madencilerin ne yaptığını ve zorluk ayarının blok süresini nasıl sabit tuttuğunu öğrenin.","related":[["mining","Kripto madenciliği (mining)","Kripto madenciliği, iş ispatı kullanan blockchain'lerde özel donanımlarla hesaplama yapılarak işlemlerin bloklara eklenmesi ve karşılığında yeni basılan coin ile işlem ücretlerinin kazanılması sürecidir."],["hash-rate","Hash oranı (hash rate)","Hash oranı, iş ispatı (proof of work) kullanan bir ağda madencilerin saniyede yaptığı toplam hash hesaplama sayısıdır ve ağın işlem gücünü ve güvenliğini gösterir."],["proof-of-stake","Hisse ispatı (Proof of Stake, PoS)","Hisse ispatı (Proof of Stake, PoS), yeni blokları üretme ve doğrulama hakkının, ağın coinini teminat olarak kilitleyen (stake eden) validatörlere verildiği bir blockchain uzlaşma mekanizmasıdır."],["blockchain","Blockchain (blok zinciri)","Blockchain (blok zinciri), işlemlerin bloklar halinde gruplanıp birbirine kriptografik olarak bağlandığı, binlerce bilgisayar tarafından ortaklaşa tutulan ve geçmişi sonradan değiştirilemeyen dijital bir kayıt defteridir."],["bitcoin-halving","Bitcoin halving (yarılanma)","Bitcoin halving (yarılanma), yaklaşık her dört yılda bir, yani her 210.000 blokta bir, madencilere verilen blok ödülünün kod gereği yarıya indirildiği olaydır."]],"lesson":null,"coin":{"slug":"bitcoin","name":"Bitcoin","symbol":"BTC"},"tool":null,"cta":false},"token-unlock":{"slug":"token-unlock","cat":"basics","en":"Token unlock","contentLocale":"tr","term":"Token kilit açılımı (token unlock)","aka":["token unlock","kilit açılması","vesting"],"short":"Token kilit açılımı (token unlock), ekip, yatırımcılar veya ekosistem fonu için önceden kilitlenmiş token'ların belirlenmiş bir takvime göre serbest bırakılıp alınıp satılabilir hale gelmesidir.","body":["Projeler, ekip ve yatırımcıların token'larını genellikle bir vesting takvimine bağlar. Tipik bir yapıda önce bir bekleme süresi (cliff) olur, ardından token'lar aylık veya günlük olarak parça parça açılır. Bazı açılımlar ise tek seferde büyük miktarlar halinde gerçekleşir.","Kilidi açılan token'lar dolaşımdaki arza eklenir. Erken yatırımcıların maliyeti piyasa fiyatından çok düşükse bir kısmının satışa geçmesi fiyat üzerinde baskı yaratabilir. Bu nedenle büyük açılımlar piyasada önceden takip edilir.",["Her açılım satış anlamına gelmez; token'lar ",["staking","staking"],"'e, ekosistem hibelerine veya hazineye gidebilir. Açılımın büyüklüğünü dolaşımdaki arza ve günlük işlem hacmine oranla değerlendirmek daha anlamlıdır. Takvimi projenin dokümantasyonundan ve token kilit takip araçlarından kontrol edebilirsiniz."]],"example":["Bir token'ın dolaşımdaki arzı 300 milyon, fiyatı 1,50 ",["USDT","usdt"]," ve günlük işlem hacmi 20 milyon USDT olsun. Gelecek hafta 45 milyon token'ın kilidi açılacak. Bu, dolaşımdaki arzın 45 / 300 = yüzde 15'i demektir ve güncel fiyatla 67,5 milyon USDT değerindedir. Bu tutar günlük hacmin üç katından fazladır. Açılan token'ların yalnızca üçte biri satışa gelse bile 22,5 milyon USDT'lik satış, bir günlük hacmin tamamını aşar."],"mistakes":["Uzun vadeli pozisyon alırken yaklaşan büyük kilit açılımlarını kontrol etmemek.","Açılan token'ların tamamının hemen satılacağını varsaymak; dağıtım ve alıcı tipi önemlidir.","Açılım miktarını mutlak sayıyla değerlendirip dolaşımdaki arza ve hacme oranlamamak."],"faq":[{"q":"Token unlock fiyatı düşürür mü?","a":"Her zaman değil. Arz artışı satış baskısı yaratabilir, ancak piyasa açılımı önceden fiyatlamış olabilir ya da açılan token'lar satılmayabilir."},{"q":"Cliff ve vesting ne demek?","a":"Cliff, token'ların hiç açılmadığı ilk bekleme süresidir. Vesting ise bu süreden sonra token'ların takvime göre kademeli olarak serbest bırakılmasıdır."}],"title":"Token unlock nedir? Kilit açılımı fiyatı etkiler mi?","description":"Token kilit açılımının ne olduğunu, cliff ve vesting kavramlarını ve büyük açılımların fiyat baskısını nasıl ölçeceğinizi öğrenin.","related":[["tokenomics","Tokenomik (tokenomics)","Tokenomik (tokenomics), bir token'ın toplam arzını, dağıtımını, kilit açılma takvimini, kullanım alanlarını ve arzı artıran ya da azaltan mekanizmaları kapsayan ekonomik tasarımıdır."],["circulating-supply","Dolaşımdaki arz (circulating supply)","Dolaşımdaki arz, bir kripto paranın şu anda piyasada serbestçe alınıp satılabilen, kilitli veya rezervde tutulmayan coin ya da token miktarıdır."],["fully-diluted-valuation","Tam seyreltilmiş değer (FDV)","Tam seyreltilmiş değer (FDV), bir token'ın güncel fiyatının maksimum veya toplam arzla çarpılmasıyla bulunan değerdir ve tüm token'lar piyasaya çıktığında projenin ne kadar büyük görüneceğini gösterir."],["airdrop","Airdrop","Airdrop, bir projenin token'larını belirli koşulları sağlayan cüzdanlara veya kullanıcılara ücretsiz olarak dağıtmasıdır; genellikle erken kullanıcıları ödüllendirmek ve token'ı geniş bir kitleye yaymak amacıyla yapılır."]],"lesson":null,"coin":null,"tool":"/coins","cta":false},"limit-order":{"slug":"limit-order","cat":"trading","en":"Limit order","contentLocale":"tr","term":"Limit emir (limit order)","aka":["limit emri","limit order","fiyatlı emir"],"short":"Limit emir (limit order), yalnızca belirlediğiniz fiyattan veya daha iyisinden gerçekleşen, piyasa o fiyata gelene kadar emir defterinde bekleyen alım ya da satım emridir.","body":["Limit alış emri, belirlediğiniz fiyatın veya daha düşük bir fiyatın; limit satış emri ise belirlediğiniz fiyatın veya daha yüksek bir fiyatın gerçekleşmesini garanti eder. Karşılığında emrin dolup dolmayacağı garanti değildir; fiyat oraya hiç gelmeyebilir.",["Emriniz defterde bekleyip ",["likidite","liquidity"]," eklediğinde maker sayılırsınız ve çoğu borsada daha düşük ücret ödersiniz. Ancak limit fiyatınız mevcut piyasa fiyatının ötesindeyse, örneğin güncel fiyatın üstünde bir limit alış verirseniz, emir anında eşleşir ve taker olarak işlem görür."],["Limit emirler kısmen de dolabilir: 1 ",["BTC","bitcoin"],"'lik emrin 0,4'ü gerçekleşip kalanı beklemeye devam edebilir. Emrin ne kadar süre geçerli kalacağını zaman geçerliliği (",["GTC","time-in-force"],", IOC, FOK) seçenekleriyle belirleyebilirsiniz."]],"example":[["ETH","ethereum"]," 3.100 ",["USDT","usdt"],"'den işlem görüyor ve siz 3.000 USDT'den 0,5 ETH almak istiyorsunuz. 3.000'e limit alış emri verirsiniz; emir defterde bekler. Fiyat iki gün sonra 2.990'a düşerse emriniz 3.000'den veya daha iyisinden dolar ve 1.500 USDT ödersiniz. Yüzde 0,02 ",["maker ücreti","maker-taker-fees"]," 0,3 USDT tutar; aynı alımı piyasa emriyle yüzde 0,05 taker ücretiyle yapsaydınız 0,75 USDT öderdiniz. Fiyat 3.010'a kadar inip geri dönerse emriniz hiç dolmaz."],"mistakes":["Limit fiyatı mevcut piyasanın ötesine koyup emrin anında taker olarak dolmasına şaşırmak.","Kısmen dolan bir emrin kalanını defterde unutup ileride istenmeyen bir anda dolmasına izin vermek.","Hızlı yükselişte limit emri inatla düşük tutup işlemi tamamen kaçırmak."],"faq":[{"q":"Limit emir neden dolmadı?","a":"Fiyat belirlediğiniz seviyeye ulaşmamış olabilir ya da ulaşsa bile o fiyatta sizden önce sırada bekleyen emirler olduğu için miktar yetmemiş olabilir."},{"q":"Limit emirde ücret daha mı düşük?","a":"Defterde bekleyip likidite eklediğinde çoğu borsada maker ücreti uygulanır ve bu genellikle taker ücretinden düşüktür. Oranlar borsaya ve hesap seviyesine göre değişir."}],"title":"Limit emir nedir? Nasıl verilir?","description":"Limit emrin nasıl çalıştığını, neden fiyat garantisi verip dolma garantisi vermediğini ve maker ücretiyle ilişkisini öğrenin.","related":[["market-order","Piyasa emri (market order)","Piyasa emri (market order), fiyat belirtmeden verilen ve emir defterindeki en iyi mevcut fiyatlardan hemen gerçekleşen alım veya satım emridir."],["post-only-order","Sadece yapıcı (post-only) emir","Sadece yapıcı (post-only) emir, yalnızca emir defterine eklenebiliyorsa kabul edilen ve anında eşleşip taker olacaksa iptal edilen bir limit emir seçeneğidir; amacı her zaman maker ücreti ödemektir."],["time-in-force","Emir geçerlilik süresi (GTC, IOC, FOK)","Emir geçerlilik süresi (time in force), bir emrin ne kadar süre aktif kalacağını ve dolmayan kısmına ne olacağını belirleyen ayardır; en yaygın seçenekler GTC, IOC ve FOK'tur."],["order-book","Emir defteri (order book)","Emir defteri (order book), bir paritede bekleyen tüm alış ve satış limit emirlerinin fiyat seviyelerine ve miktarlarına göre sıralandığı, borsanın gerçek zamanlı listesidir."],["maker-taker-fees","Maker ve taker ücretleri","Maker ve taker ücretleri, borsanın emir defterine likidite ekleyen (maker) ve defterdeki emirleri anında karşılayarak likidite çeken (taker) işlemlere uyguladığı farklı komisyon oranlarıdır."]],"lesson":{"id":"E14","slug":"market-limit-cancel","ep":14,"title":"Piyasa, limit, iptal: Her biri neyi çözer?"},"coin":null,"tool":null,"cta":true},"insurance-fund":{"slug":"insurance-fund","cat":"derivatives","en":"Insurance fund","contentLocale":"tr","term":"Sigorta fonu (Insurance fund)","aka":["insurance fund","likidasyon sigorta fonu","risk fonu"],"short":"Sigorta fonu, vadeli işlem borsalarının tasfiye edilen pozisyonların teminatı aşan zararlarını karşılamak ve otomatik kaldıraç azaltmayı (ADL) önlemek için tuttuğu rezerv fondur.","body":[["Bir pozisyon tasfiye edildiğinde borsa onu ",["likidasyon","liquidation"]," fiyatına yakın bir yerde kapatmaya çalışır. Kapanış likidasyon fiyatından daha iyi bir fiyata olursa kalan teminatın bir kısmı genellikle sigorta fonuna eklenir. Kapanış iflas fiyatından daha kötü olursa, yani teminat zararı karşılamaya yetmezse, aradaki açık sigorta fonundan ödenir."],["Böylece kâr eden karşı taraf işlemciler kazançlarını eksiksiz alır ve ",["ADL","auto-deleveraging"],"'ye başvurma ihtiyacı azalır. Büyük borsalar sigorta fonu bakiyelerini genellikle kontrat bazında veya toplu olarak herkese açık şekilde yayımlar."],["Sigorta fonunun büyüklüğü bir borsanın aşırı volatilitede ne kadar dayanıklı olduğuna dair fikir verir, ama tek başına borsanın mali sağlamlığının göstergesi değildir. Müşteri varlıklarının karşılanıp karşılanmadığını görmek için ",["rezerv kanıtı (proof of reserves)","proof-of-reserves"]," gibi ayrı göstergelere bakmak gerekir. Fonun nasıl beslendiği ve kullanıldığı borsaya göre değişir."]],"example":["Bir işlemcinin 1.000 ",["USDT","usdt"]," teminatlı long pozisyonunun iflas fiyatı 2.700 USDT, ",["likidasyon fiyatı","liquidation-price"]," 2.715 USDT olsun. Sakin bir piyasada pozisyon 2.712'den kapanırsa, iflas fiyatına göre kalan 20 × 12 = 240 USDT genellikle sigorta fonuna gider. Ani bir çöküşte pozisyon ancak 2.650'den kapatılabilirse, pozisyon 20 ",["ETH","ethereum"]," olduğu için 20 × 50 = 1.000 USDT açık oluşur ve bu açık sigorta fonundan karşılanır."],"mistakes":["Sigorta fonunun kendi tasfiye kayıplarınızı geri ödeyeceğini sanmak; fon karşı tarafı korur.","Büyük bir sigorta fonunu borsanın müşteri varlıklarını tam karşıladığının kanıtı saymak.","Likidasyonda kalan teminatın size iade edileceğini varsaymak."],"faq":[{"q":"Sigorta fonu kullanıcıları korur mu?","a":"Dolaylı olarak korur. Tasfiye edilen pozisyonun açığını kapatarak kâr eden karşı tarafın kazancını alabilmesini sağlar ve ADL ihtimalini azaltır; tasfiye edilen işlemcinin kaybını ise geri ödemez."},{"q":"Sigorta fonu biterse ne olur?","a":"Fon belirli bir kontrat için yetersiz kalırsa borsa genellikle otomatik kaldıraç azaltmaya (ADL) başvurur. Kurallar borsanın belgelerinde açıklanır."}],"title":"Sigorta fonu nedir? Vadeli işlemlerde ne işe yarar","description":"Vadeli işlem borsalarında sigorta fonunun nasıl beslendiğini, tasfiye açıklarını nasıl kapattığını ve ADL ile ilişkisini öğrenin.","related":[["auto-deleveraging","Otomatik kaldıraç azaltma (ADL)","Otomatik kaldıraç azaltma (ADL), tasfiye edilen bir pozisyonun zararı sigorta fonuyla karşılanamadığında, borsanın karşı taraftaki kârlı ve yüksek kaldıraçlı pozisyonları otomatik olarak kısmen kapatmasıdır."],["liquidation","Likidasyon (Tasfiye)","Likidasyon (tasfiye), kaldıraçlı bir pozisyonun teminatı bakım seviyesinin altına düştüğünde borsanın pozisyonu zorla kapatmasıdır."],["proof-of-reserves","Rezerv kanıtı (proof of reserves)","Rezerv kanıtı (PoR), bir kripto borsasının kullanıcılarına ait bakiyeleri karşılayacak kadar varlığı gerçekten tuttuğunu, zincir üstü adresler ve kriptografik yöntemlerle göstermeye çalıştığı denetim raporudur."],["mark-price","İşaret fiyatı (Mark price)","İşaret fiyatı (mark price), vadeli işlem borsalarının gerçekleşmemiş kâr-zararı ve likidasyonu hesaplamak için kullandığı, manipülasyona karşı dengelenmiş adil fiyattır."]],"lesson":{"id":"E23","slug":"liquidation-mark-price","ep":23,"title":"Tasfiye: Zorunlu kapatma butonuna kim bastı?"},"coin":null,"tool":"/liquidations","cta":false},"block-confirmations":{"slug":"block-confirmations","cat":"wallets-security","en":"Block confirmations","contentLocale":"tr","term":"Blok onayı (confirmation)","aka":["onay sayısı","confirmation","blok onayları"],"short":"Blok onayı, bir işlemin bir bloğa eklenmesinden sonra üzerine eklenen her yeni bloğu ifade eder; onay sayısı arttıkça işlemin geri alınması pratikte imkânsız hâle gelir.","body":[["Bir işlem önce bekleme alanında (",["mempool","mempool"],") durur. Bir bloğa dahil edildiğinde 1 onay alır; ardından gelen her blok bir onay daha ekler. ",["Blokzincir","blockchain"]," ne kadar uzarsa, o işlemi değiştirmek için gereken hesaplama veya stake miktarı o kadar büyür."],["Borsalar bir yatırmayı hesabınıza geçirmeden önce belirli bir onay sayısı bekler. Bu sayı her ağ ve her borsa için farklıdır; yatırma sayfasında genellikle \"X ağ onayı\" şeklinde yazar. ",["Bitcoin","bitcoin"],"'de bloklar ortalama 10 dakikada bir üretildiği için birkaç onay bile bir saat sürebilir; daha hızlı ağlarda onaylar saniyeler içinde birikir."],"Bazı borsalar bakiyeyi bir onay sayısında hesabınıza yansıtıp, çekim için daha fazla onay bekleyebilir. Transferiniz yavaşsa blok gezgininde onay sayısını görebilir ve borsanın istediği sayıya ne kadar kaldığını hesaplayabilirsiniz."],"example":"Bir borsaya 0,15 BTC yatırıyorsunuz ve yatırma sayfası 3 onay gerektiğini söylüyor. İşleminiz saat 14:00'te bir bloğa giriyor ve 1 onay alıyor. Bitcoin'de bloklar ortalama 10 dakikada üretildiği için 3. onay yaklaşık 14:20 civarında gelir; ancak blok süreleri rastgele olduğundan bu 14:10 da olabilir, 14:45 de. Gezginde \"3 Confirmations\" gördüğünüzde 0,15 BTC borsa hesabınıza yansır.","mistakes":["Her ağın ve borsanın aynı onay sayısını istediğini düşünmek.","Onay sayısı tamamlanmadan transferin kaybolduğunu sanıp aynı tutarı tekrar göndermek.","Yoğunlukta çok düşük ücretle gönderip işlemin bloğa girmesini uzun süre beklemek."],"faq":[{"q":"Bitcoin transferi kaç onay ister?","a":"Bu, alıcı tarafın politikasına bağlıdır. Borsalar genellikle birkaç onay ister; kesin sayı yatırma sayfasında yazar."},{"q":"0 onay ne demek?","a":"İşlem ağa yayınlanmış ama henüz bir bloğa dahil edilmemiş demektir. Bu aşamada işlem bekleme alanındadır ve kesinleşmemiştir."}],"title":"Blok onayı nedir? Transfer neden onay bekler?","description":"Blok onayının ne olduğunu, borsaların neden belirli sayıda onay beklediğini ve transfer süresinin nasıl hesaplandığını öğrenin.","related":[["transaction-hash","İşlem hash'i (TxID)","İşlem hash'i (TxID), blokzincire gönderilen her işleme verilen benzersiz kimlik kodudur ve işlemin durumunu bir blok gezgininde takip etmenizi sağlar."],["block-explorer","Blok gezgini (block explorer)","Blok gezgini, bir blockchain'deki işlemleri, adresleri ve blokları herkesin arama yapıp görebileceği şekilde listeleyen web tabanlı bir araçtır."],["mempool","Mempool (bekleyen işlem havuzu)","Mempool, gönderilmiş ama henüz bir bloğa eklenmemiş işlemlerin, madenciler veya doğrulayıcılar tarafından seçilmeyi beklediği bekleme alanıdır."],["blockchain","Blockchain (blok zinciri)","Blockchain (blok zinciri), işlemlerin bloklar halinde gruplanıp birbirine kriptografik olarak bağlandığı, binlerce bilgisayar tarafından ortaklaşa tutulan ve geçmişi sonradan değiştirilemeyen dijital bir kayıt defteridir."]],"lesson":{"id":"E10","slug":"transfer-not-arrived","ep":10,"title":"Gönderildi yazıyor ama ulaşmadı. Nereye bakmalısın?"},"coin":null,"tool":null,"cta":false},"impermanent-loss":{"slug":"impermanent-loss","cat":"defi","en":"Impermanent loss","contentLocale":"tr","term":"Geçici kayıp (impermanent loss)","aka":["impermanent loss","geçici kayıp","IL","kalıcı olmayan kayıp"],"short":"Geçici kayıp, bir likidite havuzuna yatırdığınız token'ların fiyat oranı değiştiğinde, pozisyonunuzun değerinin aynı token'ları cüzdanda tutmaya göre daha düşük kalması durumudur.","body":[[["AMM","amm"]," havuzları fiyat değiştikçe token oranlarını otomatik olarak dengeler. ",["ETH","ethereum"]," yükselirse arbitrajcılar havuzdan ETH alır, havuza ",["USDC","usdc"]," koyar. Sonuçta siz yükselen varlıktan daha az, sabit kalan varlıktan daha fazla tutmuş olursunuz. Düşüşte de tersi olur."],"Kaybın \"geçici\" denmesinin nedeni, fiyatlar yatırdığınız andaki orana geri dönerse kaybın ortadan kalkmasıdır. Ancak likiditeyi fiyat farklıyken çekerseniz kayıp kalıcı hâle gelir. Fiyat oranı ne kadar çok değişirse, hangi yönde olursa olsun kayıp o kadar büyür.",["Takas ücretleri geçici kaybı telafi edebilir. ",["Stablecoin","stablecoin"]," çiftleri (USDC/",["USDT","usdt"]," gibi) birbirine yakın fiyatta kaldığı için geçici kayıp genellikle düşüktür. Uniswap v3 gibi yoğunlaştırılmış ",["likidite","liquidity"]," modellerinde ise fiyat aralığınızın dışına çıkıldığında kayıp daha hızlı artabilir."]],"example":"ETH 1.000 USDC iken havuza 2 ETH ve 2.000 USDC yatırdığınızı varsayalım; toplam 4.000 USDC. ETH 4.000 USDC'ye çıkar. x × y = k kuralıyla havuzdaki payınız yaklaşık 1 ETH ve 4.000 USDC'ye dönüşür; değeri 8.000 USDC. Token'ları cüzdanda tutsaydınız 2 ETH × 4.000 + 2.000 = 10.000 USDC'niz olurdu. Fark 2.000 USDC, yani tutmaya göre yüzde 20 geçici kayıp. Bu süre içinde 2.000 USDC'den az ücret kazandıysanız toplamda geride kalırsınız.","mistakes":["Fiyat yükselirken de geçici kayıp yaşanabileceğini bilmemek.","Geçici kaybı hesaplamadan sadece ücret getirisine bakmak.","Kaybın her zaman geri döneceğine güvenip pozisyonu süresiz tutmak."],"faq":[{"q":"Geçici kayıp nasıl önlenir?","a":"Tamamen önlenemez, ama birbirine yakın fiyatlı çiftler seçmek ve ücret gelirini kayıpla karşılaştırmak riski azaltır."},{"q":"Geçici kayıp gerçek para kaybı mı?","a":"Likiditeyi çektiğiniz anda gerçekleşir. Pozisyon hâlâ kâr gösterebilir, ama token'ları sadece tutmaya göre daha az kazanmış olursunuz."}],"title":"Geçici kayıp (impermanent loss) nedir? Örnekle hesaplama","description":"Geçici kaybın neden oluştuğunu, örnek bir hesaplamayla ne kadar büyüyebileceğini ve likidite sağlarken nasıl değerlendirileceğini öğrenin.","related":[["liquidity-pool","Likidite havuzu (liquidity pool)","Likidite havuzu, kullanıcıların yatırdığı iki veya daha fazla token'ın bir akıllı sözleşmede kilitlendiği ve DEX'lerde takasların doğrudan bu havuzdan yapıldığı fon havuzudur."],["amm","Otomatik piyasa yapıcı (AMM)","Otomatik piyasa yapıcı (AMM), alıcı ve satıcıları bir emir defterinde eşleştirmek yerine, likidite havuzundaki token oranlarına göre fiyatı bir formülle belirleyen ve takası doğrudan havuzla yaptıran DEX modelidir."],["yield-farming","Getiri çiftçiliği (yield farming)","Getiri çiftçiliği (yield farming), kripto varlıkları DeFi protokollerine likidite, borç veya stake olarak yatırıp ücret, faiz ve ödül token'larıyla getiri elde etmeye çalışma stratejisidir."],["apr-vs-apy","APR ve APY farkı","APR, bileşik etki olmadan hesaplanan basit yıllık getiri oranıdır; APY ise kazancın düzenli olarak yeniden yatırıldığı varsayımıyla bileşik getiriyi gösterir, bu yüzden aynı oran için APY her zaman APR'den yüksek veya ona eşittir."]],"lesson":null,"coin":{"slug":"uniswap","name":"Uniswap","symbol":"UNI"},"tool":null,"cta":false},"liquid-staking":{"slug":"liquid-staking","cat":"defi","en":"Liquid staking","contentLocale":"tr","term":"Likit staking (liquid staking)","aka":["liquid staking","likit stake","LST"],"short":"Likit staking, coinlerinizi stake ederken karşılığında stake edilen pozisyonu temsil eden ve alınıp satılabilen bir token (örneğin stETH) almanızı sağlayan staking yöntemidir.","body":[["Normal ",["staking","staking"],"'de coinleriniz kilitli kalır. Likit staking protokolleri, örneğin Lido, coinlerinizi sizin adınıza doğrulayıcılara stake eder ve size bir likit staking token'ı (LST) verir. Lido'da ",["ETH","ethereum"]," karşılığında stETH alırsınız; bu token staking ödüllerini yansıtır."],["LST'yi elinizde tutarken ödül kazanmaya devam edersiniz ve aynı zamanda onu ",["DeFi","defi"],"'de teminat olarak kullanabilir, bir ",["likidite","liquidity"]," havuzuna koyabilir veya ihtiyaç anında ",["DEX","dex"],"'te satabilirsiniz. Bu, unstake bekleme süresini beklemeden çıkış yapma imkânı sunar."],["Riskler de eklenir: protokolün ",["akıllı sözleşme","smart-contract"]," riski, doğrulayıcı slashing riski ve LST'nin piyasada temsil ettiği coinden düşük fiyatlanması (depeg). Piyasada panik olduğunda LST'yi hemen satmak isteyenler bir indirim kabul etmek zorunda kalabilir."]],"example":"5 ETH'yi bir likit staking protokolüne yatırıp yaklaşık 5 stETH aldığınızı varsayalım. Bir süre sonra nakit ihtiyacınız oluyor ve bekleme kuyruğunu beklemek yerine DEX'te satmak istiyorsunuz. Piyasada stETH, ETH'ye göre yüzde 2 indirimle 0,98 ETH'den işlem görüyorsa, 5 stETH karşılığında yaklaşık 4,9 ETH alırsınız. Protokolün resmî çekim kuyruğunu kullansaydınız bu indirim yerine bekleme süresine katlanırdınız.","mistakes":["LST'nin her zaman temsil ettiği coinle birebir fiyatlanacağını sanmak.","LST'yi kaldıraçlı döngülerde kullanıp depeg durumunda tasfiye riskini görmezden gelmek.","Hangi protokolün ve sözleşmenin token'ını aldığınızı doğrulamamak."],"faq":[{"q":"Likit staking ile normal staking arasındaki fark nedir?","a":"Normal staking'de coin kilitli kalır. Likit staking'de karşılığında devredilebilir bir token alırsınız ve onu DeFi'de kullanabilir veya satabilirsiniz."},{"q":"stETH neden bazen ETH'den ucuz?","a":"Satış baskısı veya çekim kuyrukları nedeniyle piyasada indirimli işlem görebilir. Bu fark, hemen çıkmak isteyenlerin ödediği bir likidite maliyetidir."}],"title":"Likit staking nedir? stETH gibi token'lar nasıl çalışır?","description":"Likit staking'in nasıl çalıştığını, LST token'larını ve depeg ile sözleşme risklerini örnekle öğrenin.","related":[["staking","Staking (stake etme)","Staking, hisse kanıtı (proof of stake) kullanan bir blokzincirde coinlerinizi ağın güvenliği ve blok doğrulaması için kilitleyip karşılığında ağ ödülü almanızdır."],["restaking","Restaking (yeniden stake etme)","Restaking, zaten stake edilmiş ETH'yi veya likit staking token'larını başka hizmetlerin güvenliğini sağlamak için ikinci kez taahhüt ederek ek ödül kazanmayı amaçlayan bir yapıdır."],["wrapped-token","Sarılmış token (wrapped token)","Sarılmış token, başka bir varlığı birebir temsil eden ve onu farklı bir blokzincirde veya farklı bir token standardında kullanılabilir hâle getiren token'dır; örneğin WBTC, Ethereum'da Bitcoin'i temsil eder."],["depeg","Depeg (sabitin kopması)","Depeg, bir stablecoin'in bağlı olduğu değerden, örneğin 1 dolardan, belirgin ve kalıcı biçimde uzaklaşmasıdır; coin artık hedef fiyatında işlem görmez."]],"lesson":null,"coin":{"slug":"lido-dao","name":"Lido DAO","symbol":"LDO"},"tool":null,"cta":false},"restaking":{"slug":"restaking","cat":"defi","en":"Restaking","contentLocale":"tr","term":"Restaking (yeniden stake etme)","aka":["restaking","yeniden stake","LRT"],"short":"Restaking, zaten stake edilmiş ETH'yi veya likit staking token'larını başka hizmetlerin güvenliğini sağlamak için ikinci kez taahhüt ederek ek ödül kazanmayı amaçlayan bir yapıdır.","body":[["Bu modeli EigenLayer yaygınlaştırdı. Fikir şudur: ",["Ethereum","ethereum"],"'da stake edilen ETH zaten ağı koruyor; aynı stake, oracle ağları, köprüler veya veri erişilebilirliği katmanları gibi başka hizmetleri de güvence altına almak için kullanılabilir. Karşılığında bu hizmetler ek ödül öder."],["Kullanıcılar genellikle doğrudan restaking yapmaz; likit restaking protokolleri üzerinden işlem yapar ve karşılığında bir likit restaking token'ı (LRT) alır. Bu token hem ",["staking","staking"]," hem restaking ödüllerini temsil eder."],["Ek getiri, ek risk demektir. Restake edilen varlık, desteklediği hizmetlerden birinde kural ihlali olursa ek slashing'e maruz kalabilir. Üstüne birden çok ",["akıllı sözleşme","smart-contract"]," katmanı, LRT'lerde ",["depeg","depeg"]," riski ve çekim sürelerinin uzaması gelir. Bu yüzden restaking, staking'in daha karmaşık ve daha riskli bir uzantısıdır."]],"example":["10 ETH'yi ",["likit staking","liquid-staking"]," ile stake edip yıllık yaklaşık yüzde 3 ödül aldığınızı varsayalım; bu 0,3 ETH eder. Aynı pozisyonu restaking'e taşıdığınızda ek olarak yüzde 1,5 değerinde ödül vaat ediliyor; toplam beklenti 0,45 ETH. Ancak desteklenen hizmetlerden birinde bir hata nedeniyle stake'in yüzde 2'si kesilirse 0,2 ETH kaybedersiniz. Bu durumda ek 0,15 ETH ödülün tamamı ve fazlası silinmiş olur."],"mistakes":["Restaking ödüllerini normal staking ile aynı risk seviyesinde görmek.","Puan ve gelecekteki airdrop vaatlerini garanti gelir gibi hesaplamak.","LRT'lerin çekim sürelerini ve likiditesini kontrol etmemek."],"faq":[{"q":"Restaking güvenli mi?","a":"Staking'e göre ek slashing, sözleşme ve likidite riskleri taşır. Ne kadar katman eklenirse hata noktası da o kadar artar."},{"q":"LRT nedir?","a":"Likit restaking token'ı, restake edilmiş pozisyonunuzu temsil eden ve devredilebilen token'dır. Piyasa fiyatı temsil ettiği varlıktan sapabilir."}],"title":"Restaking nedir? EigenLayer ve LRT'ler nasıl çalışır?","description":"Restaking'in ne olduğunu, ek ödüllerin nereden geldiğini ve ek slashing ile likidite risklerini öğrenin.","related":[["liquid-staking","Likit staking (liquid staking)","Likit staking, coinlerinizi stake ederken karşılığında stake edilen pozisyonu temsil eden ve alınıp satılabilen bir token (örneğin stETH) almanızı sağlayan staking yöntemidir."],["staking","Staking (stake etme)","Staking, hisse kanıtı (proof of stake) kullanan bir blokzincirde coinlerinizi ağın güvenliği ve blok doğrulaması için kilitleyip karşılığında ağ ödülü almanızdır."],["validator","Validatör (doğrulayıcı)","Validatör (doğrulayıcı), hisse ispatı kullanan bir blockchain'de coin stake ederek yeni blokları öneren, diğer blokları doğrulayan ve bu iş karşılığında ödül alan düğüm operatörüdür."],["smart-contract","Akıllı kontrat (smart contract)","Akıllı kontrat (smart contract), bir blockchain üzerinde çalışan ve önceden yazılmış koşullar gerçekleştiğinde kimsenin onayına gerek kalmadan otomatik olarak işlem yapan bir programdır."]],"lesson":null,"coin":{"slug":"ethereum","name":"Ethereum","symbol":"ETH"},"tool":null,"cta":false},"defi-lending":{"slug":"defi-lending","cat":"defi","en":"DeFi lending","contentLocale":"tr","term":"DeFi borç verme (DeFi lending)","aka":["DeFi lending","kripto borç verme","merkeziyetsiz borçlanma"],"short":"DeFi borç verme, kullanıcıların kripto varlıklarını akıllı sözleşme havuzlarına yatırarak faiz kazandığı, başkalarının da bu havuzlardan teminat göstererek borç aldığı merkeziyetsiz kredi sistemidir.","body":["Aave ve Compound gibi protokollerde borç verenler varlıklarını bir havuza yatırır; borç alanlar ise önce teminat yatırır ve bu teminatın belirli bir oranına kadar borç alır. Faiz oranları havuzun kullanım oranına göre otomatik olarak değişir: havuzdaki paranın çoğu borç verildiyse oranlar yükselir.",[["DeFi","defi"]," borçları genellikle aşırı teminatlıdır; yani teminat değeri borçtan fazladır. Protokol teminat değerini oracle'lardan gelen fiyatlarla izler. Teminat değeri düşüp sağlık faktörü (health factor) 1'in altına inerse pozisyon tasfiye edilebilir; tasfiye edenler teminatın bir kısmını indirimle alır."],"İnsanlar borç alarak varlıklarını satmadan nakit ihtiyacını karşılar veya kaldıraçlı pozisyon kurar. Riskler arasında ani fiyat düşüşünde tasfiye, oracle hataları ve sözleşme açıkları vardır. Tasfiye eşikleri ve cezalar her varlık ve protokol için farklıdır."],"example":[["ETH","ethereum"]," 3.000 ",["USDC","usdc"]," iken 2 ETH'yi (6.000 USDC) teminat yatırıp 3.000 USDC borç aldığınızı varsayalım. Tasfiye eşiği yüzde 80 ise sağlık faktörünüz 6.000 × 0,8 / 3.000 = 1,6 olur. ETH 1.875 USDC'ye düşerse teminatınız 3.750 USDC olur ve 3.750 × 0,8 = 3.000, yani sağlık faktörü 1'e iner; tasfiye başlayabilir. Borcun bir kısmını ödeyerek veya teminat ekleyerek bu seviyeden uzak durabilirsiniz."],"mistakes":["Maksimum borç limitine kadar borç alıp hiç güvenlik payı bırakmamak.","Değişken faiz oranlarının artabileceğini hesaba katmamak.","Sağlık faktörünü piyasa sert hareket ederken hiç takip etmemek."],"faq":[{"q":"DeFi'de borç almak için kredi notu gerekir mi?","a":"Hayır. Borç, yatırdığınız teminatla güvence altına alınır; kimlik veya kredi geçmişi istenmez."},{"q":"Sağlık faktörü ne anlama gelir?","a":"Teminatınızın tasfiye eşiğine göre borcunuzu ne kadar karşıladığını gösterir. 1'in altına düştüğünde pozisyon tasfiye edilebilir."}],"title":"DeFi borç verme nedir? Teminat ve tasfiye nasıl işler?","description":"DeFi borç verme protokollerinin nasıl çalıştığını, aşırı teminatı, sağlık faktörünü ve tasfiye riskini örnekle öğrenin.","related":[["defi","DeFi (merkeziyetsiz finans)","DeFi (merkeziyetsiz finans), borç verme, takas, getiri elde etme gibi finansal hizmetlerin banka veya borsa yerine blokzincirdeki akıllı sözleşmelerle sunulduğu açık uygulamalar ekosistemidir."],["liquidation","Likidasyon (Tasfiye)","Likidasyon (tasfiye), kaldıraçlı bir pozisyonun teminatı bakım seviyesinin altına düştüğünde borsanın pozisyonu zorla kapatmasıdır."],["oracle","Blokzincir oracle'ı (kâhin)","Blokzincir oracle'ı, fiyatlar veya hava durumu gibi blokzincir dışındaki verileri akıllı sözleşmelere güvenilir biçimde taşıyan hizmettir; DeFi protokolleri teminat ve tasfiye hesaplarında bu verilere dayanır."],["crypto-backed-stablecoin","Kripto teminatlı stablecoin","Kripto teminatlı stablecoin, dolar rezervi yerine akıllı sözleşmede kilitlenen ETH gibi kripto varlıklarla, genellikle değerinden fazla teminatla desteklenen stablecoin'dir."],["flash-loan","Flaş kredi (flash loan)","Flaş kredi, teminat gerektirmeyen ama aynı blokzincir işlemi içinde alınıp geri ödenmesi zorunlu olan bir DeFi borcudur; geri ödenmezse tüm işlem iptal edilir."]],"lesson":null,"coin":{"slug":"aave","name":"Aave","symbol":"AAVE"},"tool":null,"cta":false},"cbdc":{"slug":"cbdc","cat":"stablecoins","en":"CBDC (central bank digital currency)","contentLocale":"tr","term":"CBDC (merkez bankası dijital parası)","aka":["CBDC","merkez bankası dijital parası","dijital Türk lirası","dijital para birimi"],"short":"CBDC, bir ülkenin merkez bankasının doğrudan çıkardığı ve resmi paranın dijital hâli olan, yasal ödeme aracı statüsündeki dijital para birimidir.","body":["Banka hesabınızdaki para aslında ticari bankanın size olan borcudur. CBDC ise doğrudan merkez bankasının yükümlülüğüdür, tıpkı nakit gibi. Çin'in dijital yuanı (e-CNY) gibi pilotlar yıllardır yürüyor; Türkiye'de de Merkez Bankası dijital Türk lirası üzerinde pilot çalışmalar yapıyor.",["CBDC ile ",["stablecoin","stablecoin"]," karıştırılmamalıdır. ",["USDT","usdt"]," veya ",["USDC","usdc"]," özel şirketlerin çıkardığı token'lardır; CBDC'yi ise devlet çıkarır. ",["Bitcoin","bitcoin"]," gibi merkeziyetsiz kripto paralardan farkı daha büyüktür: CBDC'nin arzını merkez bankası belirler ve sistem tamamen merkezi yönetilir."],"Tartışılan konular gizlilik, harcamaların izlenebilirliği ve bankaların mevduat kaybetme riskidir. Tasarım ülkeden ülkeye değişir; bazıları yalnızca bankalar arası (toptan) kullanım için düşünülür, bazıları vatandaşın cüzdanına kadar iner."],"example":"Bir ülkenin CBDC'sinin 1:1 oranla ulusal parayla aynı değerde olduğunu düşünün. 5.000 birimlik maaşınızın 1.000 birimini CBDC cüzdanınıza aktarırsınız. Market alışverişinde 250 birimlik ödeme anında merkez bankası altyapısında kesinleşir ve cüzdanınızda 750 birim kalır. Değer ulusal parayla aynı kaldığı için fiyat dalgalanması yoktur. Buna karşılık 1.000 birimlik USDT alsaydınız değer dolara bağlı olurdu ve kur değiştikçe ulusal para karşılığı da değişirdi.","mistakes":["CBDC'yi bir kripto para veya yatırım aracı sanmak.","CBDC'nin stablecoin'lerle aynı şey olduğunu düşünmek.","Her ülkenin CBDC tasarımının aynı gizlilik ve kullanım kurallarına sahip olduğunu varsaymak."],"faq":[{"q":"CBDC kripto para mı?","a":"Hayır. CBDC, merkez bankasının çıkardığı resmi paranın dijital hâlidir. Blockchain benzeri teknoloji kullanabilir ama merkeziyetsiz değildir ve fiyatı ulusal parayla sabittir."},{"q":"Dijital Türk lirası kullanıma açıldı mı?","a":"Merkez Bankası dijital Türk lirası için pilot ve test çalışmaları yürütmektedir. Genel kullanıma açılma takvimi için resmi duyuruları takip etmek gerekir."}],"title":"CBDC nedir? Merkez bankası dijital parası anlamı","description":"CBDC nedir, dijital Türk lirası gibi merkez bankası paraları stablecoin ve Bitcoin'den nasıl ayrılır, kısa ve net öğrenin.","related":[["stablecoin","Stablecoin (sabit coin)","Stablecoin, değerini genellikle ABD doları gibi bir referans varlığa sabitlemeyi amaçlayan ve kripto piyasasında nakit gibi kullanılan bir kripto paradır."],["fiat-on-ramp","Fiat giriş kanalı (fiat on-ramp)","Fiat giriş kanalı (on-ramp), Türk lirası, dolar veya euro gibi geleneksel parayı kripto varlığa çevirmenizi sağlayan yol ya da hizmettir; banka havalesi, kartla alım ve P2P bunun örnekleridir."],["kyc","KYC (müşterini tanı)","KYC (Know Your Customer, müşterini tanı), kripto borsalarının ve finansal kuruluşların kullanıcının kimliğini, adresini ve bazen gelir kaynağını doğruladığı zorunlu kimlik doğrulama sürecidir."],["blockchain","Blockchain (blok zinciri)","Blockchain (blok zinciri), işlemlerin bloklar halinde gruplanıp birbirine kriptografik olarak bağlandığı, binlerce bilgisayar tarafından ortaklaşa tutulan ve geçmişi sonradan değiştirilemeyen dijital bir kayıt defteridir."]],"lesson":{"id":"E02","slug":"is-usdt-a-dollar","ep":2,"title":"USDT dolar mı? Kripto alırken neden her yerde karşımıza çıkar?"},"coin":null,"tool":null,"cta":false},"node":{"slug":"node","cat":"onchain","en":"Node","contentLocale":"tr","term":"Düğüm (node)","aka":["node","düğüm","full node","tam düğüm"],"short":"Düğüm (node), bir blockchain ağına bağlanan, işlemleri ve blokları doğrulayan, yayan ve çoğu zaman zincirin bir kopyasını saklayan bilgisayar veya yazılımdır.","body":[[["Blockchain","blockchain"]," tek bir sunucuda değil, binlerce düğümde çalışır. Tam düğüm (full node) tüm kuralları kendisi kontrol eder: geçersiz bir işlem veya blok gelirse reddeder. Bu sayede kimsenin kuralları tek başına değiştirmesi mümkün olmaz."],["Düğüm türleri farklıdır. Arşiv düğümleri tüm geçmiş durumu saklar, hafif düğümler (light client) yalnızca gerekli veriyi alır. ",["Bitcoin","bitcoin"],"'de madenciler blok üretir, düğümler ise bu blokları doğrular. Proof of stake ağlarında doğrulayıcılar (",["validator","validator"],") da birer düğüm çalıştırır ama stake ile blok önerme sorumluluğu üstlenir."],"Cüzdanınız da arka planda bir düğüme bağlanır; çoğu zaman bu bir RPC sağlayıcısının düğümüdür. Kendi düğümünüzü çalıştırmak, bakiyenizi ve işlemlerinizi üçüncü bir tarafa güvenmeden doğrulamanızı sağlar."],"example":"Kendi evinizde bir Bitcoin tam düğümü kurmak istediğinizi düşünün. Zincirin tamamı birkaç yüz gigabayt yer kaplar, bu yüzden 1 TB SSD'li bir mini bilgisayar seçersiniz. İlk senkronizasyon internet hızınıza göre bir iki gün sürebilir. Sonrasında aylık veri kullanımı yüzlerce gigabayta ulaşabilir. Karşılığında cüzdanınızı kendi düğümünüze bağlar ve 0,05 BTC'lik bir ödemenin gerçekten 3 onay aldığını başka bir siteye sormadan kendiniz görürsünüz.","mistakes":["Düğüm çalıştırmanın madencilik yapmakla aynı şey olduğunu düşünmek.","Her düğüm çalıştırmanın otomatik ödül getirdiğini sanmak; Bitcoin tam düğümleri ödül almaz.","Disk ve bant genişliği ihtiyacını hesaplamadan kurulum yapmak."],"faq":[{"q":"Node çalıştırmak para kazandırır mı?","a":"Bitcoin tam düğümü doğrudan gelir sağlamaz, size bağımsız doğrulama imkânı verir. Bazı proof of stake ağlarında doğrulayıcı düğümleri stake karşılığında ödül alır."},{"q":"Full node ile light node farkı nedir?","a":"Full node tüm blokları indirip kuralları baştan sona kendisi kontrol eder. Light node ise az veri indirir ve bazı bilgiler için tam düğümlere güvenir."}],"title":"Node nedir? Blockchain düğümü ne işe yarar","description":"Blockchain'de node (düğüm) nedir, full node ve light node farkı nedir, kendi düğümünüzü çalıştırmak ne kazandırır, öğrenin.","related":[["blockchain","Blockchain (blok zinciri)","Blockchain (blok zinciri), işlemlerin bloklar halinde gruplanıp birbirine kriptografik olarak bağlandığı, binlerce bilgisayar tarafından ortaklaşa tutulan ve geçmişi sonradan değiştirilemeyen dijital bir kayıt defteridir."],["validator","Validatör (doğrulayıcı)","Validatör (doğrulayıcı), hisse ispatı kullanan bir blockchain'de coin stake ederek yeni blokları öneren, diğer blokları doğrulayan ve bu iş karşılığında ödül alan düğüm operatörüdür."],["mining","Kripto madenciliği (mining)","Kripto madenciliği, iş ispatı kullanan blockchain'lerde özel donanımlarla hesaplama yapılarak işlemlerin bloklara eklenmesi ve karşılığında yeni basılan coin ile işlem ücretlerinin kazanılması sürecidir."],["mempool","Mempool (bekleyen işlem havuzu)","Mempool, gönderilmiş ama henüz bir bloğa eklenmemiş işlemlerin, madenciler veya doğrulayıcılar tarafından seçilmeyi beklediği bekleme alanıdır."]],"lesson":null,"coin":{"slug":"bitcoin","name":"Bitcoin","symbol":"BTC"},"tool":null,"cta":false},"aml":{"slug":"aml","cat":"regulation","en":"AML (anti-money laundering)","contentLocale":"tr","term":"AML (kara para aklamayı önleme)","aka":["AML","kara para aklamayla mücadele","suç gelirlerinin aklanmasının önlenmesi"],"short":"AML (Anti-Money Laundering), suç gelirlerinin finansal sistemde temiz para gibi gösterilmesini önlemeye yönelik yasal kurallar, kontroller ve izleme süreçlerinin bütünüdür.","body":[[["KYC","kyc"]," müşterinin kim olduğunu öğrenmekse, AML o müşterinin işlemlerini sürekli izlemektir. Borsalar büyük veya alışılmadık transferleri, yaptırım listesindeki adreslerle ilişkiyi ve karıştırıcı (mixer) servislerden gelen coin'leri tarar. Türkiye'de şüpheli işlem bildirimleri MASAK'a yapılır; diğer ülkelerin de kendi mali istihbarat birimleri vardır."],["Bu kontroller sizi de etkiler. Bir yatırma riskli bir adresle bağlantılı görünürse borsa bakiyeyi geçici olarak dondurabilir ve kaynak belgesi isteyebilir. ",["P2P","p2p-trading"]," işlemlerde, tanımadığınız kişilerden gelen ödemeler de bu tür incelemelere yol açabilir."],"Kurallar ülkeye göre farklıdır ama mantık aynıdır: fonun nereden geldiğini açıklayabilmek. Banka dekontlarını, borsa işlem geçmişini ve cüzdan adreslerinizi düzenli saklamak, olası bir incelemeyi hızla çözmenizi sağlar."],"example":["Bir arkadaşınızın size 3.000 ",["USDT","usdt"]," gönderdiğini düşünün. Bu coin'lerin bir kısmı geçmişte yaptırım listesindeki bir adresten geçmiş. Borsanın izleme sistemi yatırmayı işaretler ve hesabınızda 3.000 USDT 'inceleniyor' durumunda kalır. Sizden bu transferin nedenini ve gönderenin bilgilerini isterler. Elinizde bir yazışma ve ödeme kaydı varsa süreç birkaç günde kapanabilir. Hiçbir belge yoksa fon uzun süre kilitli kalabilir veya iade edilebilir."],"mistakes":["Tanımadığınız kişilerden kripto veya para alıp borsaya yatırmak.","Hesabınızı başkasının parasını geçirmek için kullandırmak.","Büyük işlemlerin kaynak belgelerini saklamamak."],"faq":[{"q":"Borsa hesabım AML yüzünden neden dondu?","a":"Bir işleminiz risk sistemine takılmış olabilir; örneğin riskli bir adresle bağlantı veya alışılmadık bir tutar. Borsa genellikle fon kaynağını gösteren belge ister."},{"q":"KYC ile AML arasındaki fark nedir?","a":"KYC hesabı açarken kimliğinizi doğrular. AML ise hesabınızdaki işlemleri sürekli izleyerek suç gelirlerinin sisteme girmesini önlemeye çalışır."}],"title":"AML nedir? Kripto borsalarında kara para kontrolü","description":"AML nedir, kripto borsaları işlemlerinizi nasıl izler, hesap neden dondurulur ve inceleme sürecini nasıl hızlandırırsınız.","related":[["kyc","KYC (müşterini tanı)","KYC (Know Your Customer, müşterini tanı), kripto borsalarının ve finansal kuruluşların kullanıcının kimliğini, adresini ve bazen gelir kaynağını doğruladığı zorunlu kimlik doğrulama sürecidir."],["travel-rule","Seyahat kuralı (travel rule)","Seyahat kuralı (travel rule), kripto hizmet sağlayıcılarının belirli transferlerde gönderen ve alıcı bilgilerini birbirine iletmesini zorunlu kılan, FATF'ın 16 numaralı tavsiyesine dayanan kuraldır."],["vasp","VASP (sanal varlık hizmet sağlayıcısı)","VASP (Virtual Asset Service Provider), başkaları adına kripto varlık alım satımı, takası, transferi veya saklaması yapan ve bu nedenle düzenlemeye tabi olan şirketlerdir."],["p2p-trading","P2P alım satım (C2C)","P2P alım satım, kullanıcıların borsanın aracılık ettiği bir pazarda, kripto varlığı birbirlerinden banka transferi gibi ödeme yöntemleriyle doğrudan aldığı veya sattığı işlem türüdür."]],"lesson":{"id":"E05","slug":"kyc-who-gets-your-id","ep":5,"title":"KYC nasıl yapılır ve kimlik kime verilmelidir?"},"coin":null,"tool":null,"cta":false},"tokenized-gold":{"slug":"tokenized-gold","cat":"tokenized-assets","en":"Tokenized gold","contentLocale":"tr","term":"Tokenize altın","aka":["altın token'ı","tokenized gold","PAXG","XAUT"],"short":"Tokenize altın, her biri belirli miktarda fiziki altına, genellikle bir troy onsa karşılık gelen ve bu altın bir kasada saklanan, blockchain üzerinde transfer edilebilen token'dır.","body":["En bilinen örnekler Paxos'un PAX Gold (PAXG) ve Tether'in Tether Gold (XAUT) token'larıdır. Her iki token da bir troy ons altına karşılık gelecek şekilde tasarlanmıştır ve ihraççılar altının belirli kasalarda tutulduğunu belirtir. Token'ı kesirli olarak alabilirsiniz; örneğin 0,05 ons.","Fiziki altına göre avantajları: saklama ve taşıma derdi yok, 7/24 transfer edilebilir ve bazı platformlarda teminat olarak kullanılabilir. Bankadaki altın hesabından farkı ise zincir üstünde olması ve kendi cüzdanınızda tutulabilmesidir.","Riskler: ihraççının gerçekten altını tuttuğuna güvenirsiniz, bu yüzden denetim raporları önemlidir. Fiziki altına çevirme genellikle yüksek minimum tutar ve ek ücretlerle mümkündür. Token'ın borsadaki fiyatı, kısa süreli olarak altın spot fiyatından sapabilir."],"example":["Altının ons fiyatının 2.400 dolar olduğunu varsayalım. 600 ",["USDT","usdt"]," ile yaklaşık 0,25 adet altın token'ı alırsınız, bu 0,25 ons altına karşılık gelir. Altın yüzde 5 yükselip 2.520 dolara çıkarsa token'larınız 630 USDT eder. Borsada alım ve satışta yüzde 0,1 ücret öderseniz toplam yaklaşık 1,23 USDT ücret çıkar ve net kazancınız 28,77 USDT olur. TL bazında sonuç, dolar/TL kuruna da bağlıdır."],"mistakes":["Tokenize altının arkasındaki kasa ve denetim bilgilerini kontrol etmemek.","Token'ı kolayca fiziki altına çevirebileceğinizi varsaymak.","Token'ı desteklemeyen bir ağa veya cüzdana göndermek."],"faq":[{"q":"PAXG ve XAUT gerçek altınla mı destekleniyor?","a":"İhraççılar her token için bir troy ons fiziki altını kasada tuttuklarını belirtir. Güven için düzenli yayımlanan denetim veya doğrulama raporlarını takip etmek gerekir."},{"q":"Tokenize altın mı yoksa fiziki altın mı?","a":"Tokenize altın taşıma ve saklama açısından pratiktir ama ihraççı riskine dayanır. Fiziki altın ise doğrudan sizdedir ama saklama ve alım-satım makası maliyetleri vardır."}],"title":"Tokenize altın nedir? PAXG ve XAUT nasıl çalışır","description":"Tokenize altın nedir, PAXG ve XAUT gibi token'lar fiziki altınla nasıl desteklenir ve hangi riskleri taşır, örnekle öğrenin.","related":[["real-world-assets","Gerçek dünya varlıkları (RWA)","Gerçek dünya varlıkları (RWA), devlet tahvilleri, altın, gayrimenkul, krediler veya hisseler gibi blockchain dışındaki varlıkların zincir üstünde token olarak temsil edilmesidir."],["stablecoin","Stablecoin (sabit coin)","Stablecoin, değerini genellikle ABD doları gibi bir referans varlığa sabitlemeyi amaçlayan ve kripto piyasasında nakit gibi kullanılan bir kripto paradır."],["custodial-wallet","Emanetçi cüzdan (Custodial wallet)","Emanetçi cüzdan (custodial wallet), kripto varlıklarınızın özel anahtarlarını sizin yerinize bir borsanın veya saklama kuruluşunun tuttuğu cüzdan türüdür."],["tokenized-stocks","Tokenize hisse senetleri","Tokenize hisse senetleri, bir şirketin hisse senedinin fiyatını takip eden ve genellikle bir saklayıcıda tutulan gerçek hisseyle desteklenen, blockchain üzerinde işlem gören token'lardır."]],"lesson":null,"coin":{"slug":"pax-gold","name":"PAX Gold","symbol":"PAXG"},"tool":"/topics/tokenized-assets","cta":false}});
